namespace sv_56b16c697ad14d009fca7f7ef2f06c13.Services;

/// <summary>
/// Scoped service that manages low-stock alert polling and notifies all subscribers
/// when new data arrives. Scoped lifetime ensures each user circuit gets its own instance.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private Timer? _timer;
    private int _subscriberCount;
    private readonly object _lock = new();

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Fired when polling detects new alert data. All subscribed components update.
    /// </summary>
    public event Action? OnAlertDataChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query for items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(Random.Shared.Next(0, 16));
    }

    /// <summary>
    /// Call when a component that needs polling becomes active.
    /// Starts the 10-second polling timer on the first subscriber.
    /// </summary>
    public void Subscribe()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
            {
                StartPolling();
            }
        }
    }

    /// <summary>
    /// Call when a component that needs polling is disposed.
    /// Stops the timer when no subscribers remain.
    /// </summary>
    public void Unsubscribe()
    {
        lock (_lock)
        {
            _subscriberCount--;
            if (_subscriberCount <= 0)
            {
                _subscriberCount = 0;
                StopPolling();
            }
        }
    }

    private void StartPolling()
    {
        _timer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
    }

    private void StopPolling()
    {
        _timer?.Dispose();
        _timer = null;
    }

    private async void PollCallback(object? state)
    {
        var count = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        CurrentLowStockCount = count;
        OnAlertDataChanged?.Invoke();
    }

    private void OnWarehouseChanged()
    {
        // When warehouse changes, immediately re-poll if active
        if (_timer is not null)
        {
            _timer.Change(TimeSpan.Zero, TimeSpan.FromSeconds(10));
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        StopPolling();
    }
}

