@page "/dashboard"
@rendermode InteractiveServer
@inject sv_56b16c697ad14d009fca7f7ef2f06c13.Services.WarehouseState WarehouseState
@inject sv_56b16c697ad14d009fca7f7ef2f06c13.Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <h5 class="mb-0">@WarehouseState.SelectedWarehouseName — Inventory Alerts</h5>
    </div>
    <div class="card-body">
        <p>
            Low-stock items:
            <span class="badge bg-@(AlertService.CurrentLowStockCount > 5 ? "danger" : AlertService.CurrentLowStockCount > 0 ? "warning" : "success") fs-5">
                @AlertService.CurrentLowStockCount
            </span>
        </p>
        <p class="text-muted mb-0">
            Polling every 10 seconds for <strong>@WarehouseState.SelectedWarehouseName</strong>.
            Last updated: @_lastUpdated.ToString("HH:mm:ss")
        </p>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;
    private DateTime _lastUpdated = DateTime.Now;

    protected override void OnInitialized()
    {
        // Subscribe to start polling (first subscriber starts the timer)
        AlertService.Subscribe();

        _alertHandler = () => InvokeAsync(() =>
        {
            _lastUpdated = DateTime.Now;
            StateHasChanged();
        });
        AlertService.OnAlertDataChanged += _alertHandler;

        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _warehouseHandler;
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.Unsubscribe();
    }
}

